INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (1, 'Web Hosting', 'web-hosting', 'server', 'Linux and Windows shared hosting for business websites, with cPanel/Plesk control, free SSL options and email on your own domain.', '## What shared web hosting is\n\nShared hosting places your website on a professionally managed server alongside other sites. The server, network and security patching are handled for you, which keeps costs low and removes the need for in-house server skills. For most company websites, portfolios, brochure sites and small online stores, shared hosting is the right starting point.\n\n## Who it suits\n\n- Small and medium businesses launching or moving a company website\n- Professionals such as doctors, CAs and consultants who need a reliable online presence\n- Agencies and freelancers hosting client brochure sites\n- Anyone moving from a free website builder to their own domain\n\n## Linux or Windows hosting?\n\nChoose **Linux hosting** for PHP, MySQL, WordPress, Joomla or static HTML sites. It is the most common choice and is managed through cPanel. Choose **Windows hosting** when your site is built with ASP.NET or needs MS SQL, and manage it through Plesk.\n\n## What to check before you buy\n\n1. Storage and bandwidth that match your expected traffic\n2. How many websites, databases and email accounts are included\n3. Whether SSL certificates can be installed easily\n4. Backup options and how restores work\n5. How to upgrade when you outgrow shared resources\n\n## Growing beyond shared hosting\n\nIf your site starts receiving heavy traffic or needs custom server software, you can move to [VPS hosting](/services/vps-hosting) or a [dedicated server](/services/dedicated-servers) without changing your domain or email setup.', 'Linux (cPanel) and Windows (Plesk) plans\nEmail accounts on your own domain\nOne-click installs for WordPress and popular apps\nSSL certificate support for HTTPS\nIndian and US data-centre options\nUpgrade path to VPS or cloud hosting', 'shared web hosting', 'https://syscom.co.in/web-hosting/index.php', 'Web Hosting in India for Business Websites', 'Linux and Windows shared web hosting for Indian businesses: control panel, SSL, email accounts and support to get your website online quickly.', 1, 'published');
INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (2, 'WordPress Hosting', 'wordpress-hosting', 'wordpress', 'Hosting tuned for WordPress with one-click installation, server-level caching and an environment configured for common plugins and themes.', '## Why WordPress-specific hosting helps\n\nWordPress powers a large share of business websites, but a default server setup is not always a good fit. Optimized WordPress hosting configures PHP, the database and caching around how WordPress actually works, so pages load faster and the admin dashboard stays responsive.\n\n## Good fit for\n\n- Company websites and blogs built on WordPress\n- WooCommerce stores with a moderate product catalogue\n- Agencies managing several WordPress client sites\n- Content teams publishing articles regularly\n\n## Performance basics that still matter\n\nEven on tuned hosting, site speed depends on your choices:\n\n- Use a lightweight, well-maintained theme\n- Keep plugins to the ones you actually use\n- Compress images before uploading them\n- Keep WordPress core, themes and plugins updated\n\n## Security for WordPress sites\n\nMost WordPress compromises come from outdated plugins and weak passwords. Combine updates and strong passwords with an [SSL certificate](/services/ssl-certificates) and regular off-site backups. Our guide to [website backups](/blog/website-backup-strategy-small-business) explains a simple plan you can follow.', 'One-click WordPress installation\nServer configuration tuned for WordPress\nCaching for faster page loads\nSSL support for secure logins\nCompatible with popular themes and plugins\nOptional malware scanning and backups', 'managed wordpress hosting', 'https://syscom.co.in/optimized-wordpress-hosting.php', 'Optimized WordPress Hosting in India', 'WordPress hosting tuned for speed and stability: one-click install, caching, SSL support and help from a team that understands WordPress sites.', 2, 'published');
INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (3, 'VPS Hosting', 'vps-hosting', 'layers', 'Linux KVM virtual private servers with dedicated resources and root access for growing websites, applications and development teams.', '## What a VPS gives you\n\nA Virtual Private Server (VPS) splits a physical server into isolated virtual machines. Each VPS has its own allocated CPU, memory and storage, its own operating system and full root access. You get much of the control of a dedicated server at a lower cost.\n\n## When to move to a VPS\n\n- Your shared hosting account regularly hits resource limits\n- You need to install custom software, services or a specific PHP/Node/Python version\n- You run several sites or applications and want them on one server you control\n- You need a staging or development environment that mirrors production\n\n## KVM virtualisation\n\nKVM (Kernel-based Virtual Machine) provides full virtualisation: your VPS runs its own kernel and is not affected by other tenants\' configuration. This makes resource allocation predictable.\n\n## Managed or unmanaged?\n\nWith an unmanaged VPS your team handles the operating system, updates and security. If you do not have a system administrator, consider managed add-ons or stay on [web hosting](/services/web-hosting) until you do. For the heaviest workloads, compare with [dedicated servers](/services/dedicated-servers).', 'KVM virtualisation with dedicated resources\nFull root access\nChoice of Linux distributions\nScale CPU, RAM and storage as you grow\nOptional managed services and add-ons\nIsolated from other customers\' workloads', 'vps hosting india', 'https://syscom.co.in/virtualserverlinux-hosting.php', 'Linux KVM VPS Hosting in India', 'KVM-based Linux VPS hosting with guaranteed resources and full root access for applications, busy websites and development environments.', 3, 'published');
INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (4, 'Dedicated Servers', 'dedicated-servers', 'cpu', 'Linux and Windows dedicated servers when an application needs the full power, isolation and configuration control of physical hardware.', '## Full hardware, no neighbours\n\nA dedicated server is a physical machine used only by your organisation. All CPU cores, memory, disks and network capacity are available to your applications, which makes performance predictable under load.\n\n## Typical workloads\n\n- High-traffic websites and online stores\n- Large databases and reporting systems\n- ERP, CRM and other line-of-business applications\n- Hosting many client sites for an agency or reseller\n\n## Linux or Windows\n\nPick Linux for open-source stacks (PHP, MySQL, Node.js, Python) and Windows Server when your applications depend on .NET, MS SQL Server or other Microsoft technologies.\n\n## Planning checklist\n\n1. Estimate peak CPU, RAM and storage needs with headroom\n2. Decide who will manage patching, monitoring and backups\n3. Plan a backup and disaster-recovery process before going live\n4. Secure access with SSH keys or strong passwords and a firewall\n\nIf your needs are smaller, a [VPS](/services/vps-hosting) often gives enough control at a lower cost.', 'Entire physical server for your workloads\nLinux or Windows operating systems\nFull administrative access\nOptional managed server services\nSuitable for databases and ERP workloads\nPredictable performance with no neighbours', 'dedicated server india', 'https://syscom.co.in/dedicated-servers.php', 'Linux & Windows Dedicated Servers', 'Dedicated Linux and Windows servers for high-traffic sites, databases and business applications that need full hardware resources and control.', 4, 'published');
INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (5, 'Domain Registration', 'domain-registration', 'globe', 'Register, transfer and manage domain names across popular extensions including .com, .in and .co.in, with DNS management included.', '## Your domain is your online identity\n\nA domain name is the address customers type to find you and the part after the @ in your business email. A short, memorable domain builds trust and is an asset you keep even if you change hosting provider.\n\n## Choosing an extension\n\n- **.in / .co.in** signal an Indian business and suit companies serving Indian customers\n- **.com** is widely recognised internationally\n- **New extensions** such as .online or .store can work when the name you want is taken elsewhere\n\nOur guide on [how to choose a domain name](/blog/how-to-choose-a-domain-name) walks through naming rules in detail.\n\n## Transfers\n\nYou can move an existing domain to SYSCOM. The domain must usually be unlocked at the current registrar, you need its authorisation (EPP) code, and it should be more than 60 days past registration or a previous transfer.\n\n## Protect the domain\n\n- Turn on auto-renew so the domain never lapses\n- Keep the registrant email address current\n- Keep registrar login details secure\n\nPair your domain with [business email](/services/business-email) and [web hosting](/services/web-hosting) to get fully online.', 'Popular extensions including .com, .in and .co.in\nNew gTLDs, premium and IDN domains\nDomain transfer to SYSCOM\nDNS management\nBulk registration for portfolios\nRenewal reminders', 'domain registration india', 'https://syscom.co.in/domain-registration/index.php', 'Domain Name Registration & Transfer', 'Search, register and transfer domain names including .com, .in and .co.in. Manage DNS, renewals and privacy from one control panel.', 5, 'published');
INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (6, 'Business Email', 'business-email', 'mail', 'Professional email on your own domain, with options including Business Email, Titan, Google Workspace and enterprise email hosting.', '## Why a domain email matters\n\nAn address like name@yourcompany.in tells customers they are dealing with an established business. It also keeps company communication under company control: when an employee leaves, the mailbox stays with the business.\n\n## Choosing the right plan\n\n- **Business Email** – cost-effective mailboxes for small teams\n- **Titan Business Email** – a modern mail app with calendar and productivity features\n- **Google Workspace** – Gmail on your domain plus Docs, Drive and Meet\n- **Enterprise Email** – larger mailboxes and admin controls for bigger teams\n\n## Deliverability basics\n\nSet up SPF, DKIM and DMARC DNS records so your messages are trusted by receiving servers and less likely to land in spam. These records live in your [domain\'s DNS](/services/domain-registration).\n\nRead [business email vs free email](/blog/business-email-vs-free-email) for a fuller comparison.', 'Email addresses on your own domain\nWebmail, desktop and mobile access\nSpam and virus filtering\nTitan Business Email option\nGoogle Workspace option\nEnterprise email for larger teams', 'professional email address', 'https://syscom.co.in/business-email', 'Business Email Hosting on Your Domain', 'Professional email addresses on your own domain with Business Email, Titan and Google Workspace options, webmail, mobile access and spam filtering.', 6, 'published');
INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (7, 'SSL Certificates', 'ssl-certificates', 'lock', 'SSL/TLS certificates that enable HTTPS, encrypt data between visitors and your site, and remove "Not secure" browser warnings.', '## What an SSL certificate does\n\nAn SSL (TLS) certificate lets your website use HTTPS. It encrypts information travelling between the visitor\'s browser and your server, such as passwords, contact form entries and payment details, and proves the site belongs to your domain.\n\n## Certificate types\n\n| Type | Validates | Good for |\n| --- | --- | --- |\n| Domain Validation (DV) | Domain control | Blogs, brochure sites |\n| Organisation Validation (OV) | Domain and company | Business websites |\n| Extended Validation (EV) | Strict company checks | Finance, large e-commerce |\n| Wildcard | One domain and all its subdomains | Sites using many subdomains |\n\n## HTTPS and search\n\nGoogle has confirmed HTTPS as a lightweight ranking signal, and browsers label HTTP pages that collect data as "Not secure". Moving to HTTPS is a basic step for trust and for search. See [what an SSL certificate is](/blog/what-is-an-ssl-certificate) for a step-by-step migration checklist.', 'Domain, organisation and extended validation options\nSingle-domain, multi-domain and wildcard certificates\nEncrypts data in transit with HTTPS\nRemoves browser "Not secure" warnings\nInstallation help with your hosting\nRenewal reminders', 'ssl certificate india', 'https://syscom.co.in/digital-certificate', 'SSL Certificates for HTTPS Websites', 'Secure your website with an SSL certificate: HTTPS encryption, browser trust and protection for logins, forms and payments on your site.', 7, 'published');
INSERT INTO services (id, name, slug, icon, description, content, features, primary_keyword, external_url, meta_title, meta_description, sort_order, status) VALUES (8, 'Reseller Hosting', 'reseller-hosting', 'users', 'Linux and Windows reseller hosting for agencies and freelancers who want to host client websites under their own brand.', '## Build recurring revenue from hosting\n\nReseller hosting lets web designers, developers and agencies host client websites under their own brand. You buy a pool of resources and divide it into separate accounts, each with its own control panel login.\n\n## Why agencies use it\n\n- Keep client websites isolated from each other\n- Offer hosting, [domains](/services/domain-registration) and [SSL](/services/ssl-certificates) as one package\n- Earn recurring income instead of one-off project fees\n- Control the support relationship with your clients\n\n## Running it well\n\n1. Define clear packages with storage and email limits\n2. Put backups and renewals in writing in your client agreements\n3. Monitor resource use so one client does not affect others\n4. Move demanding clients to a [VPS](/services/vps-hosting) when they outgrow shared resources', 'Separate control panel accounts per client\nCreate your own hosting packages\nLinux (WHM/cPanel) and Windows options\nSell domains and SSL alongside hosting\nOne bill for all client accounts\nUpgrade as your client base grows', 'reseller hosting india', 'https://syscom.co.in/reseller-hosting.php', 'Linux & Windows Reseller Hosting', 'Reseller hosting for web designers and agencies: create separate client accounts, set your own packages and grow a hosting business.', 8, 'published');
INSERT INTO faqs (question, answer, sort_order, status) VALUES ('What does SYSCOM offer?', 'SYSCOM provides domain registration, Linux and Windows web hosting, WordPress hosting, VPS and dedicated servers, reseller hosting, business email and SSL certificates for businesses in India.', 1, 'published');
INSERT INTO faqs (question, answer, sort_order, status) VALUES ('I am new to websites. Where should I start?', 'Start by registering a domain name, then choose a web hosting plan and business email. If you plan to use WordPress, WordPress-optimised hosting is a good first choice.', 2, 'published');
INSERT INTO faqs (question, answer, sort_order, status) VALUES ('Can I transfer my existing domain and website to SYSCOM?', 'Yes. Domains can be transferred with the authorisation code from your current registrar, and websites can be migrated to a new hosting account before DNS is switched.', 3, 'published');
INSERT INTO faqs (question, answer, sort_order, status) VALUES ('Do I need an SSL certificate?', 'Yes. SSL enables HTTPS, which encrypts data between visitors and your site and prevents browsers from marking your pages as "Not secure".', 4, 'published');
INSERT INTO faqs (question, answer, sort_order, status) VALUES ('How do I get help choosing a plan?', 'Send us your requirements through the contact form and our team will recommend a suitable domain, hosting and email setup.', 5, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (1, 'How many websites can I host on one plan?', 'It depends on the plan. Entry plans usually host a single website, while higher plans allow multiple websites, databases and email accounts.', 1, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (1, 'Can I upgrade my hosting plan later?', 'Yes. You can move to a larger shared plan, WordPress hosting or a VPS as your website grows.', 2, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (2, 'Can I migrate my existing WordPress site?', 'Yes. Your files and database can be moved to WordPress hosting, and the site tested before DNS is switched.', 1, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (3, 'Do I get root access on a VPS?', 'Yes. Linux KVM VPS plans include full root access so you can install and configure the software you need.', 1, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (3, 'Is a VPS managed?', 'A VPS is self-managed by default. Managed services and add-ons are available if you do not have a system administrator.', 2, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (4, 'Should I choose Linux or Windows for my dedicated server?', 'Choose Linux for PHP, MySQL, Node.js or Python applications and Windows Server for .NET or MS SQL Server workloads.', 1, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (5, 'What do I need to transfer a domain?', 'The domain should be unlocked at the current registrar, you need its authorisation (EPP) code, and it usually must be more than 60 days old.', 1, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (5, 'Can I register a .in domain?', 'Yes. .in and .co.in domains are available alongside .com and many other extensions.', 2, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (6, 'Will my email work on my phone?', 'Yes. Business email works with webmail, desktop email apps and mobile devices.', 1, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (7, 'How long does it take to issue an SSL certificate?', 'Domain-validated certificates are usually issued quickly after validation. Organisation and extended validation certificates take longer because the company is verified.', 1, 'published');
INSERT INTO faqs (service_id, question, answer, sort_order, status) VALUES (8, 'Can my clients have their own control panel?', 'Yes. Each client account gets its own control panel login, isolated from other clients.', 1, 'published');
INSERT INTO posts (id, title, slug, excerpt, content, primary_keyword, meta_title, meta_description, service_id, author_id, status, published_at, created_at, updated_at) VALUES (1, 'How to Choose the Right Web Hosting Plan for Your Business in India', 'how-to-choose-web-hosting-india', 'Hosting decides how fast, secure and reliable your website is. Use this checklist to compare plans on the things that actually matter.', 'Your hosting plan is the foundation of your website. It affects page speed, security, email reliability and how easily you can grow. Yet many businesses pick a plan on price alone and only discover the limits later. This guide gives you a clear way to compare options.\n\n## Start with what your website needs to do\n\nWrite down, in plain language, what the site is for:\n\n- A brochure site that explains your services and collects enquiries\n- A blog or resource centre you will publish to every week\n- An online store with payments and customer accounts\n- A web application with custom software\n\nA five-page company website has very different needs from a store with thousands of products. Being specific stops you from overpaying or under-buying.\n\n## Understand the hosting types\n\n**Shared web hosting** puts your site on a managed server with other websites. It is affordable and needs no server skills, which makes it right for most small business sites.\n\n**WordPress hosting** is shared hosting configured specifically for WordPress, with caching and settings tuned for it.\n\n**VPS hosting** gives you a private slice of a server with guaranteed resources and root access.\n\n**Dedicated servers** give you an entire physical machine for heavy or sensitive workloads.\n\nIf you are unsure, read our comparison of [shared, VPS and dedicated hosting](/blog/shared-vs-vps-vs-dedicated-hosting).\n\n## Check server location\n\nFor a business whose customers are mostly in India, a server in or near India usually means lower latency and faster first loads. If your audience is global, a content delivery network (CDN) can help regardless of where the server is.\n\n## Compare resources honestly\n\nLook past the headline numbers:\n\n1. **Storage type** – SSD or NVMe storage is noticeably faster than older disks.\n2. **Bandwidth** – "unmetered" plans still have fair-use limits; read them.\n3. **CPU and memory limits** – these matter more than storage for busy sites.\n4. **Websites, databases and email accounts** – count how many you need today and next year.\n\n## Security is not optional\n\nMake sure the plan supports an SSL certificate so your site runs on HTTPS. Ask how the server is patched, whether malware scanning is available and how backups work. A backup you cannot restore quickly is not much help.\n\n## Look at support and upgrade paths\n\nFind out how you contact support and what is covered. Also check how you move to a bigger plan: a smooth path from shared hosting to a VPS saves a painful migration later.\n\n## A simple decision checklist\n\n| Question | If yes, consider |\n| --- | --- |\n| Is it a small business or brochure site? | Shared web hosting |\n| Is it built on WordPress? | WordPress hosting |\n| Do you need custom software or root access? | VPS hosting |\n| Do you have heavy traffic or large databases? | Dedicated server |\n\nChoosing well now means fewer surprises later. Start with the plan that fits today, and make sure it can grow with you.', 'how to choose web hosting', 'How to Choose Web Hosting for an Indian Business', 'A practical checklist for choosing web hosting in India: hosting types, server location, resources, security, support and upgrade paths.', 1, 1, 'published', '2026-08-11 10:00:00', '2026-08-11 10:00:00', '2026-08-11 10:00:00');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (1, 'Is cheap web hosting good enough for a business website?', 'For a small brochure site, an entry-level shared plan is often enough. Check the resource limits, SSL support and backup options rather than price alone, and make sure you can upgrade easily.', 1, 'published');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (1, 'Does server location affect SEO?', 'Server location mainly affects speed for your visitors. Faster pages give a better experience, which supports SEO indirectly. For local targeting, content, language and your domain matter more than server location.', 2, 'published');
INSERT INTO posts (id, title, slug, excerpt, content, primary_keyword, meta_title, meta_description, service_id, author_id, status, published_at, created_at, updated_at) VALUES (2, 'Shared vs VPS vs Dedicated Hosting: Which One Do You Need?', 'shared-vs-vps-vs-dedicated-hosting', 'The three main hosting types differ in isolation, control and the skills they need. Here is how to decide without overspending.', 'The biggest hosting decision is not which company to use but which *type* of hosting fits your workload. Shared, VPS and dedicated hosting trade off cost, control and responsibility in different ways.\n\n## Shared hosting\n\nMany websites share one server\'s CPU, memory and disk. The provider manages everything at server level.\n\n- **Best for:** company websites, blogs, small stores, portfolios\n- **You manage:** your website files, databases and email accounts\n- **Limitation:** resource limits apply, and you cannot install custom server software\n\n## VPS hosting\n\nA physical server is divided into isolated virtual machines. Your VPS has allocated resources and its own operating system.\n\n- **Best for:** growing sites, several applications, development environments\n- **You manage:** the operating system, security updates and software (unless you choose managed services)\n- **Limitation:** needs Linux administration skills\n\n## Dedicated servers\n\nYou rent an entire physical server.\n\n- **Best for:** high-traffic platforms, large databases, ERP and compliance-sensitive workloads\n- **You manage:** everything from the operating system upward\n- **Limitation:** highest cost, and capacity planning is your responsibility\n\n## Side-by-side comparison\n\n| | Shared | VPS | Dedicated |\n| --- | --- | --- | --- |\n| Isolation | Low | High | Complete |\n| Root access | No | Yes | Yes |\n| Skills needed | Minimal | Moderate | Advanced |\n| Relative cost | Lowest | Medium | Highest |\n| Scaling | Upgrade plan | Resize VPS | New hardware |\n\n## Signs you have outgrown shared hosting\n\n1. Pages slow down at busy times even after optimising images and plugins\n2. You regularly hit CPU or process limits\n3. You need software the shared server does not allow\n4. You want to separate several important sites\n\n## A practical path\n\nMost businesses start on shared or WordPress hosting, move to a VPS when they need more control, and only then consider dedicated hardware. Moving step by step keeps cost aligned with real needs. Whatever you choose, run your site on HTTPS and keep off-site backups.\n\n## Questions to ask before you decide\n\n- How much traffic do you expect at your busiest time, not on an average day?\n- Does anyone on your team have Linux administration experience?\n- Do you need software or versions the provider\'s shared servers do not offer?\n- Who will apply security updates, monitor the server and restore backups?\n- What does it cost to move up a tier later, and how is the migration handled?\n\nHonest answers to these questions usually point clearly to one option. If they do not, start with the simpler choice: it is easier to upgrade than to run infrastructure you are not ready to manage.', 'shared vs vps hosting', 'Shared vs VPS vs Dedicated Hosting Compared', 'Compare shared, VPS and dedicated hosting on performance, control, security and management effort to pick the right option for your site.', 3, 1, 'published', '2026-08-18 10:00:00', '2026-08-18 10:00:00', '2026-08-18 10:00:00');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (2, 'Is a VPS faster than shared hosting?', 'Usually, because resources are allocated to you rather than shared. Real-world speed still depends on how well your site and server are configured.', 1, 'published');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (2, 'Can I move from shared hosting to a VPS later?', 'Yes. Your domain stays the same; the website files, databases and email are migrated to the new server and DNS is updated.', 2, 'published');
INSERT INTO posts (id, title, slug, excerpt, content, primary_keyword, meta_title, meta_description, service_id, author_id, status, published_at, created_at, updated_at) VALUES (3, 'How to Choose a Domain Name for Your Business: A Practical Checklist', 'how-to-choose-a-domain-name', 'A good domain is short, easy to say and hard to misspell. Follow these rules before you register one.', 'Your domain name appears on your website, email addresses, visiting cards and invoices. Changing it later is expensive, so it is worth a little thought up front.\n\n## Keep it short and easy to say\n\nSay the name aloud to someone and ask them to type it. If they hesitate or misspell it, simplify. Shorter names are easier to remember and less likely to be mistyped.\n\n## Avoid hyphens and numbers\n\nHyphens and digits are hard to communicate by voice ("is that the number 4 or the word four?"). Use them only when there is no alternative.\n\n## Choose the right extension\n\n- **.in** or **.co.in** – clearly Indian, good for businesses serving Indian customers\n- **.com** – the most familiar global extension\n- **New extensions** – such as .online or .tech, useful when your preferred name is taken\n\nMany businesses register both the .in and .com versions and point one to the other so customers reach them either way.\n\n## Use your brand, not a string of keywords\n\nExact-match keyword domains no longer carry special weight in Google. A brandable name that people remember builds more value over time than a long keyword phrase.\n\n## Check trademarks and social handles\n\nBefore you register, search for existing trademarks and check whether matching social media usernames are available. It is far easier to adjust a name now than after a dispute.\n\n## Protect the domain after registration\n\n1. Turn on auto-renew so the domain never expires by accident\n2. Use a registrant email address you will keep for years\n3. Enable domain lock to prevent unauthorised transfers\n4. Store registrar login details securely and limit who can access them\n\n## Put the domain to work\n\nA domain on its own is just an address. Connect it to web hosting for your website and to business email so every message you send reinforces your brand.\n\n## Common mistakes to avoid\n\n- **Registering in an employee\'s personal name** – always register the domain to the business so ownership is clear.\n- **Letting a web designer hold the only login** – make sure the business has its own registrar account access.\n- **Ignoring renewal emails** – an expired domain takes your website and email offline, and some expired names are bought by others.\n- **Choosing a name that is hard to spell** – every misspelling is a customer who cannot find you or whose email bounces.', 'how to choose a domain name', 'How to Choose a Domain Name: Business Checklist', 'Pick a domain name customers remember: length, spelling, .in vs .com, trademarks, and how to protect the domain once it is registered.', 5, 1, 'published', '2026-08-25 10:00:00', '2026-08-25 10:00:00', '2026-08-25 10:00:00');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (3, 'Should I buy .in or .com for my business?', 'If most customers are in India, .in or .co.in is a strong choice. Registering both and redirecting one to the other protects your brand.', 1, 'published');
INSERT INTO posts (id, title, slug, excerpt, content, primary_keyword, meta_title, meta_description, service_id, author_id, status, published_at, created_at, updated_at) VALUES (4, 'What Is an SSL Certificate and Why Does Your Website Need One?', 'what-is-an-ssl-certificate', 'SSL certificates turn HTTP into HTTPS. Here is what they protect, which type to choose and how to switch without losing traffic.', 'When a browser shows a padlock next to a web address, the site is using HTTPS, made possible by an SSL (more accurately TLS) certificate. Without one, browsers show a "Not secure" warning on pages that collect information.\n\n## What SSL protects\n\nAn SSL certificate encrypts data moving between the visitor and your server. That includes:\n\n- Login usernames and passwords\n- Contact and enquiry form submissions\n- Payment and personal details\n\nIt also confirms the visitor is connected to the real site for your domain, not an impostor.\n\n## Types of certificate\n\n**Domain Validation (DV)** confirms you control the domain. It is issued quickly and suits blogs and brochure sites.\n\n**Organisation Validation (OV)** also verifies your company, adding a layer of trust for business websites.\n\n**Extended Validation (EV)** involves the strictest company checks and is often used by financial and large e-commerce sites.\n\n**Wildcard** certificates cover a domain and all its first-level subdomains.\n\n## HTTPS, trust and search\n\nGoogle has said HTTPS is a lightweight ranking signal. More importantly, visitors are less likely to fill in a form on a page marked "Not secure". HTTPS is now a baseline expectation.\n\n## Checklist for moving to HTTPS\n\n1. Install the certificate on your hosting account\n2. Update your site\'s base URL to https://\n3. Redirect every HTTP URL to its HTTPS version with a 301 redirect\n4. Update internal links, images and scripts to use HTTPS to avoid mixed-content warnings\n5. Update canonical tags and your XML sitemap\n6. Add the HTTPS property in Google Search Console and submit the sitemap\n\n## Remember renewals\n\nCertificates expire. Keep renewal reminders active, or your visitors will see a full-page security warning instead of your website.\n\n## Fixing mixed-content warnings\n\nAfter switching to HTTPS, some pages may still show a warning because an image, script or stylesheet is loaded over plain HTTP. Common causes are:\n\n- Hard-coded `http://` links in old posts or theme files\n- Third-party widgets or embeds that still use HTTP\n- Images inserted with a full HTTP URL in page builders\n\nUse your browser\'s developer tools to find the insecure resources, then update them to HTTPS or to relative URLs. Once every resource loads securely, the padlock appears on every page.', 'what is ssl certificate', 'What Is an SSL Certificate? A Plain-English Guide', 'Learn what an SSL certificate does, the types available, how HTTPS affects trust and search, and a checklist for moving your site to HTTPS.', 7, 1, 'published', '2026-09-01 10:00:00', '2026-09-01 10:00:00', '2026-09-01 10:00:00');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (4, 'Is a free SSL certificate enough?', 'For many brochure sites a domain-validated certificate is enough to enable HTTPS. Businesses that want company details verified choose OV or EV certificates.', 1, 'published');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (4, 'Will moving to HTTPS hurt my rankings?', 'Not if you use permanent 301 redirects from every HTTP URL, update internal links and canonicals, and submit the HTTPS sitemap.', 2, 'published');
INSERT INTO posts (id, title, slug, excerpt, content, primary_keyword, meta_title, meta_description, service_id, author_id, status, published_at, created_at, updated_at) VALUES (5, 'Business Email vs Free Email: Why a Custom Domain Email Matters', 'business-email-vs-free-email', 'Free email accounts are fine for personal use. For a business they cost you trust, control and deliverability.', 'Many small businesses start with a free email account. It works, but as the business grows the limits show: customers question the address, staff leave with mailboxes, and messages land in spam.\n\n## Trust starts with the address\n\nAn email from accounts@yourcompany.in looks established. An email from yourcompany123@ a free provider looks temporary, and it is also easier for scammers to imitate.\n\n## The business owns the mailbox\n\nWith business email, the company controls every mailbox. When someone leaves, you can reset the password, forward the mail or keep the history. With free personal accounts, the mailbox belongs to the individual.\n\n## Better deliverability\n\nBusiness email on your domain lets you publish SPF, DKIM and DMARC records. These tell receiving servers which systems may send email for your domain, which helps legitimate messages reach inboxes and makes spoofing harder.\n\n## Security and administration\n\nBusiness plans give an administrator control over:\n\n- Creating and removing users\n- Password policies and, on many plans, two-step verification\n- Aliases such as sales@ and support@ that route to the right people\n\n## Choosing a plan\n\n| Need | Suitable option |\n| --- | --- |\n| A few mailboxes at low cost | Business Email |\n| Modern mail app with calendar | Titan Business Email |\n| Documents, video calls and shared drives | Google Workspace |\n| Large teams with compliance needs | Enterprise Email |\n\n## Setting it up\n\n1. Register or choose your domain\n2. Pick an email plan and create mailboxes\n3. Update the domain\'s MX records to point to the email service\n4. Add SPF, DKIM and DMARC records\n5. Configure email apps on desktops and phones\n\nBusiness email is one of the lowest-cost upgrades that makes a company look and operate more professionally.\n\n## Avoiding problems during the switch\n\n- **Lower the DNS TTL a day in advance** so the MX change takes effect quickly.\n- **Create every mailbox before switching MX records** so no incoming mail bounces.\n- **Keep the old accounts active for a few weeks** in case someone still sends to them.\n- **Tell your team which apps to reconfigure** on phones and laptops, and share the new settings in writing.', 'custom domain email', 'Business Email vs Free Email for Companies', 'Why companies use email on their own domain instead of free accounts: trust, control, deliverability and security, plus how to set it up.', 6, 1, 'published', '2026-09-08 10:00:00', '2026-09-08 10:00:00', '2026-09-08 10:00:00');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (5, 'Can I keep my website hosting and email with different providers?', 'Yes. Email is controlled by your domain\'s MX records, so it can point to a different service from your website hosting.', 1, 'published');
INSERT INTO posts (id, title, slug, excerpt, content, primary_keyword, meta_title, meta_description, service_id, author_id, status, published_at, created_at, updated_at) VALUES (6, 'Website Backups: A Practical 3-2-1 Plan for Small Businesses', 'website-backup-strategy-small-business', 'Hacks, bad updates and accidental deletions happen. A tested backup plan turns a disaster into a short interruption.', 'Websites break for ordinary reasons: a plugin update goes wrong, someone deletes the wrong folder, or malware gets in through an outdated component. The businesses that recover quickly are the ones with a backup plan they have actually tested.\n\n## What needs backing up\n\n- **Website files** – code, themes, plugins and uploaded images\n- **Databases** – your content, orders, users and settings\n- **Email** – if your mailboxes are on the same hosting account\n- **Configuration** – DNS records, SSL details and important settings\n\n## The 3-2-1 rule\n\nKeep **3** copies of your data, on **2** different types of storage, with **1** copy off-site. For a website that usually means the live site, a backup on the hosting server and another copy stored somewhere else entirely.\n\n## How often to back up\n\nMatch frequency to how often the site changes:\n\n| Site type | Suggested frequency |\n| --- | --- |\n| Brochure site that rarely changes | Weekly, plus before every update |\n| Blog publishing several times a week | Daily |\n| Online store taking orders | Daily or more often, including the database |\n\n## Automate it\n\nManual backups get forgotten. Use automated tools that run on a schedule, keep several versions, and store copies away from the server. Services such as CodeGuard for websites or Acronis for wider infrastructure are designed for this.\n\n## Test your restores\n\nA backup is only useful if you can restore it. Every few months:\n\n1. Restore a recent backup to a staging location\n2. Check that pages, images and forms work\n3. Note how long it took and any missing pieces\n4. Update your plan based on what you learn\n\n## Combine backups with prevention\n\nBackups are your safety net. Keep software updated, use strong passwords, run your site on HTTPS and scan for malware to reduce how often you need them.\n\n## When something goes wrong\n\n1. **Stay calm and stop changes** – do not keep editing a broken or compromised site.\n2. **Identify the last good backup** – choose a point before the problem started.\n3. **Restore to staging first** if possible, and confirm the site works.\n4. **Fix the cause** – update the plugin, change passwords or remove the malicious code.\n5. **Restore to production** and keep a note of what happened for next time.\n\nHaving these steps written down in advance means anyone on the team can follow them under pressure.', 'website backup', 'Website Backup Plan for Small Businesses (3-2-1)', 'A simple 3-2-1 website backup plan: what to back up, how often, where to keep copies, and how to test restores before you need them.', 1, 1, 'published', '2026-09-15 10:00:00', '2026-09-15 10:00:00', '2026-09-15 10:00:00');
INSERT INTO faqs (post_id, question, answer, sort_order, status) VALUES (6, 'Are my hosting provider\'s backups enough?', 'They help, but keep at least one copy that you control and that is stored off the hosting server. That protects you if the account itself is compromised.', 1, 'published');
INSERT INTO landing_pages (id, title, slug, primary_keyword, meta_title, meta_description, hero_subtitle, problem, solution, features, benefits, use_cases, content, cta_text, service_id, status) VALUES (1, 'Web Hosting in India for Growing Businesses', 'web-hosting-india', 'web hosting india', 'Web Hosting in India for Growing Businesses', 'Business web hosting in India with Linux and Windows plans, SSL, domain email and an upgrade path to VPS as your website grows.', 'Get your business website online on managed Linux or Windows hosting, with email on your domain and room to grow.', 'Many Indian small businesses still rely on a free website builder or an old hosting account nobody remembers the login for. Pages load slowly, there is no HTTPS, email addresses are on free providers, and nobody knows whether a backup exists. Every one of these makes the business look less trustworthy to a first-time visitor.', 'SYSCOM web hosting gives you a managed server environment, a control panel to run your site and mailboxes, and support for SSL certificates so every page loads over HTTPS. When your site grows you can move to WordPress-optimised hosting, a VPS or a dedicated server without changing your domain.', 'Linux and Windows plans: cPanel for PHP/MySQL and WordPress sites, Plesk for ASP.NET applications\nEmail on your domain: create mailboxes such as sales@ and support@ from the same control panel\nSSL support: run every page on HTTPS and remove browser warnings\nOne-click installers: set up WordPress and other common applications in minutes\nData-centre choice: host close to your customers for faster page loads', 'A professional web presence that you control\nFaster, more secure pages for visitors\nOne place to manage website, email and domain\nA clear upgrade path instead of a painful migration later', 'Local service businesses: a fast site with contact forms, maps and service pages that bring in enquiries\nProfessionals and consultants: a credible portfolio or practice website with a domain email address\nSmall online stores: a WooCommerce or similar store that can move to a VPS as orders increase', '## Getting started\n\n1. Choose or transfer your domain name\n2. Pick a Linux or Windows plan based on how your site is built\n3. Install your website or migrate your existing files and database\n4. Enable SSL and create your business mailboxes\n\nNot sure which plan fits? Our guide on [how to choose web hosting](/blog/how-to-choose-web-hosting-india) walks through the decision.', 'Get hosting advice', 1, 'published');
INSERT INTO faqs (landing_page_id, question, answer, sort_order, status) VALUES (1, 'Which hosting plan should a small business start with?', 'Most small business websites start well on a Linux shared hosting plan. If the site is built on WordPress, WordPress-optimised hosting is a good alternative.', 1, 'published');
INSERT INTO faqs (landing_page_id, question, answer, sort_order, status) VALUES (1, 'Can you move my existing website?', 'Yes. The site files, database and email can be migrated to your new hosting account, then DNS is switched once everything has been checked.', 2, 'published');
INSERT INTO faqs (landing_page_id, question, answer, sort_order, status) VALUES (1, 'Do I get email with web hosting?', 'Hosting plans include email accounts on your domain. For larger teams, dedicated business email plans such as Titan or Google Workspace are also available.', 3, 'published');
INSERT INTO landing_pages (id, title, slug, primary_keyword, meta_title, meta_description, hero_subtitle, problem, solution, features, benefits, use_cases, content, cta_text, service_id, status) VALUES (2, 'WordPress Hosting in India, Tuned for Speed', 'wordpress-hosting-india', 'wordpress hosting india', 'WordPress Hosting in India, Tuned for Speed', 'Optimised WordPress hosting for Indian businesses and agencies: one-click install, caching, SSL and a server setup built around WordPress.', 'Hosting configured around WordPress, so your pages load faster and your dashboard stays responsive.', 'A WordPress site on a generic hosting setup often feels sluggish: the admin dashboard is slow, pages take seconds to appear, and plugins time out during updates. Slow pages frustrate visitors and make it harder for your content to perform.', 'Optimised WordPress hosting configures the web server, PHP and caching specifically for WordPress. Combined with good site practices such as a lightweight theme, fewer plugins and compressed images, it gives your content a fast, stable home.', 'One-click WordPress: install a fresh site in minutes with secure defaults\nWordPress-aware caching: serve repeat page views faster\nPHP configured for WordPress: sensible memory and execution limits for plugins and page builders\nSSL for secure logins: protect wp-admin and customer forms with HTTPS\nSecurity add-ons: optional malware scanning and automated backups', 'Faster pages and a smoother editing experience\nLess time spent fixing server settings\nA secure base for WooCommerce and membership sites\nRoom to scale to a VPS for high-traffic sites', 'Content-led businesses: publish articles and guides that attract organic search traffic\nAgencies: host and maintain several client WordPress sites on a consistent setup\nWooCommerce stores: run a catalogue and checkout on a setup built for WordPress', '## Keep your WordPress site healthy\n\n- Update WordPress core, themes and plugins regularly\n- Remove plugins you no longer use\n- Keep automatic off-site backups\n- Use strong passwords and limit administrator accounts\n\nRead our [website backup plan](/blog/website-backup-strategy-small-business) for a simple routine.', 'Talk to a WordPress specialist', 2, 'published');
INSERT INTO faqs (landing_page_id, question, answer, sort_order, status) VALUES (2, 'What is the difference between WordPress hosting and regular hosting?', 'WordPress hosting uses a server configuration, caching and defaults chosen specifically for WordPress, while regular shared hosting is set up for many kinds of applications.', 1, 'published');
INSERT INTO faqs (landing_page_id, question, answer, sort_order, status) VALUES (2, 'Can I host WooCommerce on WordPress hosting?', 'Yes. Small and medium WooCommerce stores run well on optimised WordPress hosting. Large catalogues with heavy traffic may need a VPS.', 2, 'published');
INSERT INTO landing_pages (id, title, slug, primary_keyword, meta_title, meta_description, hero_subtitle, problem, solution, features, benefits, use_cases, content, cta_text, service_id, status) VALUES (3, 'Business Email Hosting on Your Own Domain', 'business-email-hosting-india', 'business email hosting india', 'Business Email Hosting in India on Your Domain', 'Professional email on your company domain with Business Email, Titan or Google Workspace: better trust, admin control and deliverability.', 'Move your team from free email accounts to professional addresses on your own domain.', 'When a business uses free email accounts, customers see addresses that are easy to imitate, messages are more likely to be filtered as spam, and the company loses access to important conversations when an employee leaves.', 'Business email hosting puts every mailbox on your company domain under central administration. Add SPF, DKIM and DMARC records to improve deliverability, and choose the plan that matches how your team works, from simple mailboxes to Google Workspace.', 'Mailboxes on your domain: name@yourcompany.in for every team member\nMultiple plan options: Business Email, Titan, Google Workspace and enterprise email\nWebmail and mobile access: read and send mail on any device\nSpam and virus filtering: keep inboxes clean and safer\nCentral administration: add, remove and reset users from one place', 'Customers instantly recognise and trust your emails\nThe business keeps ownership of every mailbox\nBetter inbox placement with proper DNS authentication\nConsistent branding across every message you send', 'Growing teams: give each new hire a company address on day one\nSales and support desks: shared aliases like sales@ and support@ routed to the right people\nCompanies replacing free accounts: migrate existing mail to professional mailboxes', '## Moving from free email\n\n1. Choose a plan and create mailboxes for your team\n2. Point your domain\'s MX records to the new email service\n3. Add SPF, DKIM and DMARC records\n4. Import old mail if you need the history\n\nCompare options in [business email vs free email](/blog/business-email-vs-free-email).', 'Set up business email', 6, 'published');
INSERT INTO faqs (landing_page_id, question, answer, sort_order, status) VALUES (3, 'Can I use business email with my existing domain?', 'Yes. You keep your domain and point its MX records to the email service. Your website can stay where it is.', 1, 'published');
INSERT INTO faqs (landing_page_id, question, answer, sort_order, status) VALUES (3, 'Which is better: Titan or Google Workspace?', 'Titan focuses on email with a modern app at a lower cost; Google Workspace adds Docs, Drive, Meet and other collaboration tools. Choose based on how your team works.', 2, 'published');
